files.content:
.switch{
  display:inline-flex;
  align-items:center;
  gap:var(--s-2);
  cursor:pointer;
  font-size:var(--t-small);
  color:var(--obsidian-100);
}
.switch input{
  appearance:none;
  width:var(--s-8);
  height:calc(var(--s-4) + var(--s-0-5));
  background:var(--obsidian-700);
  border-radius:var(--r-full);
  position:relative;
  transition:background var(--d-quick) var(--ease-standard);
}
.switch input::after{
  content:"";
  position:absolute;
  top:var(--s-0-5);
  left:var(--s-0-5);
  width:14px;
  height:14px;
  background:var(--obsidian-200);
  border-radius:var(--r-full);
  transition:left var(--d-base) var(--ease-standard), background var(--d-quick) var(--ease-standard);
}
.switch input:checked{
  background:var(--primary-500);
}
.switch input:checked::after{
  left:var(--s-4);
  background:var(--obsidian-950);
}
.switch input:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
.switch input:disabled{
  opacity:0.4;
  cursor:not-allowed;
}
.switch:has(input:disabled){
  color:var(--obsidian-400);
  cursor:not-allowed;
}
